mapper.select:
SELECT ,
       s.name AS student_name, s.student_no AS student_no,
       u.real_name AS counselor_name
FROM student_record l
LEFT JOIN student s ON l.student_id = s.id
LEFT JOIN sys_user u ON l.counselor_id = u.id

    l.record_type = 'LEAVE'
    AND s.name LIKE CONCAT('%', #{studentName}, '%')
    AND l.category = #{leaveType}
    AND l.status = #{status}
    AND l.student_id = #{studentId}
    AND l.counselor_id = #{counselorId}

ORDER BY CASE l.status WHEN '待审批' THEN 0 WHEN '已批准' THEN 1 ELSE 2 END, l.create_time DESC, l.id DESC

mapper.update:
UPDATE student_record
student_id = #{studentId}, category = #{leaveType}, start_date = #{startDate}, end_date = #{endDate}, days = #{days}, reason = #{reason}, status = #{status}, counselor_id = #{counselorId}, approve_time = #{approveTime},
WHERE record_type = 'LEAVE' AND id = #{id}
